    // A department's budget is set
    //   GIVEN (nothing)
    //   WHEN  SetBudget(budget=100000)
    //   THEN  Department Budget Set(budget=100000)
    [Fact]
    public async Task ADepartmentSBudgetIsSet()
    {
        await WhenPosting(_ =>
        {
            _.Post.Json(new SetBudget(SeedData.DepartmentId, 100_000m))
                .ToUrl($"/departments/{SeedData.DepartmentId}/budget");
            _.StatusCodeShouldBe(204);
        });

        var events = await EventsFor(SeedData.DepartmentId);
        events.ShouldHaveSingleItem()
            .ShouldBeOfType<DepartmentBudgetSet>()
            .Budget.ShouldBe(100_000m);
    }

    // The budget may be raised at any time
    //   GIVEN Department Budget Set(budget=100000)
    //   WHEN  SetBudget(budget=150000)
    //   THEN  Department Budget Set(budget=150000)
    [Fact]
    public async Task TheBudgetMayBeRaisedAtAnyTime()
    {
        await Given(SeedData.DepartmentId, new DepartmentBudgetSet(SeedData.DepartmentId, 100_000m));

        await WhenPosting(_ =>
        {
            _.Post.Json(new SetBudget(SeedData.DepartmentId, 150_000m))
                .ToUrl($"/departments/{SeedData.DepartmentId}/budget");
            _.StatusCodeShouldBe(204);
        });

        // A SECOND event, not an edited first one. The stream is the history: "raised" means both values
        // are on the record, and the latest wins only when the state is folded.
        var events = await EventsFor(SeedData.DepartmentId);
        events.Length.ShouldBe(2);
        events[^1].ShouldBeOfType<DepartmentBudgetSet>().Budget.ShouldBe(150_000m);
    }
